@Serializable
data class Todo(var id: Long, var text: String)

@Composable
fun TodoApp() {
  var todos by rememberPyreonStorage<List<Todo>>("todos", listOf())
  var draft by remember { mutableStateOf("") }
  fun add() {
    todos = (todos + listOf(Todo(id = System.currentTimeMillis(), text = draft)))
    draft = ""
  }
  fun remove(id: Long) {
    todos = todos.filter({ t -> t.id != id })
  }
