import { signal } from '@pyreon/reactivity'
import { For } from '@pyreon/core'
import { useStorage } from '@pyreon/storage'
import { Stack, Inline, Text, Field, Button } from '@pyreon/primitives'

type Todo = { id: number; text: string }

export function TodoApp() {
  const todos = useStorage<Todo[]>('todos', [])
  const draft = signal('')

  const add = () => {
    todos.set([...todos(), { id: Date.now(), text: draft() }])
    draft.set('')
  }
  const remove = (id: number) => todos.set(todos().filter((t) => t.id !== id))

  return (
    <Stack gap="md">
      <Field value={draft} onChangeText={(text) => draft.set(text)} placeholder="What needs doing?" />
      <Button onPress={add}>Add</Button>
      <For each={todos} by={(t) => t.id}>
        {(t) => (
          <Inline gap="sm">
            <Text>{t.text}</Text>
            <Button onPress={() => remove(t.id)}>Remove</Button>
          </Inline>
        )}
      </For>
    </Stack>
  )
}

