import { signal, computed } from '@pyreon/reactivity'
import { onMount } from '@pyreon/core'
import { Stack, Text, Button } from '@pyreon/primitives'

export function Countdown() {
  const left = signal(10)
  const done = computed(() => left() === 0)

  onMount(() => {
    const id = setInterval(() => {
      if (left() > 0) left.set(left() - 1)
    }, 1000)
    return () => clearInterval(id)
  })

  return (
    <Stack gap="md">
      <Text>{done() ? 'Lift off' : `T-minus ${left()}`}</Text>
      <Button onPress={() => left.set(10)}>Restart</Button>
    </Stack>
  )
}

import { signal, computed } from '@pyreon/reactivity'
import { Stack, Inline, Text, Button } from '@pyreon/primitives'

enum Plan {
  Free = 'free',
  Pro = 'pro',
}

// Shared by every component in this file: one observable singleton natively.
const plan = signal<Plan>(Plan.Free)
const seats = signal(1)
const monthly = computed(() => (plan() === Plan.Pro ? 12 * seats() : 0))

export function PriceBadge() {
  return <Text>{`$${monthly()} a month`}</Text>
}

export function PlanPicker() {
  return (
    <Stack gap="md">
      <Inline gap="sm">
        <Button onPress={() => plan.set(Plan.Free)}>Free</Button>
        <Button onPress={() => plan.set(Plan.Pro)}>Pro</Button>
      </Inline>
      <Button onPress={() => seats.set(seats() + 1)}>Add a seat</Button>
      <Text>{`${seats()} seats`}</Text>
      <PriceBadge />
    </Stack>
  )
}

import { signal } from '@pyreon/reactivity'
import { Stack, Field, Text, Button } from '@pyreon/primitives'

type Contact = { name: string; email: string }

export function ImportContacts() {
  const raw = signal('')
  const count = signal(0)
  const problem = signal('')

  const importNow = () => {
    try {
      const list = JSON.parse(raw()) as Contact[]
      count.set(list.length)
      problem.set('')
    } catch (e) {
      problem.set('That is not a contact list')
    }
  }

  return (
    <Stack gap="md">
      <Field value={raw} onChangeText={(t) => raw.set(t)} placeholder="Paste JSON" />
      <Button onPress={importNow}>Import</Button>
      <Text>{problem() === '' ? `${count()} contacts` : problem()}</Text>
    </Stack>
  )
}
